mapper.select:
SELECT id, content_id, account_id, task_id, platform, content_type, content_title, content_text, original_url, publish_time, capture_time, risk_level, sentiment, keywords, like_count, comment_count, share_count, collect_count, view_count, raw_data, clue_id, deleted, create_user_id, update_user_id, create_time, update_time FROM campus_account_content WHERE deleted = 0
AND account_id = #{accountId}
AND task_id = #{taskId}
AND risk_level = #{riskLevel}
AND ( content_title LIKE CONCAT('%', #{keyword}, '%') OR content_text LIKE CONCAT('%', #{keyword}, '%') OR keywords LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY publish_time DESC, id DESC

SELECT id, content_id, account_id, task_id, platform, content_type, content_title, content_text, original_url, publish_time, capture_time, risk_level, sentiment, keywords, like_count, comment_count, share_count, collect_count, view_count, raw_data, clue_id, deleted, create_user_id, update_user_id, create_time, update_time FROM campus_account_content WHERE deleted = 0
AND capture_time >= #{startTime}
AND capture_time <= #{endTime}
ORDER BY capture_time DESC, id DESC
